async function listAllResources(session) {
  let resources = [];
  let cursor = undefined;

  while (true) {
    const params = cursor ? { cursor } : {};
    const response = await session.request("resources/list", params);
    resources = resources.concat(response.resources);

    if (!response.nextCursor) break;
    cursor = response.nextCursor;
  }

  return resources;
}

function listResources(cursor, pageSize = 100) {
  const offset = cursor ? decodeCursor(cursor) : 0;
  const page = allResources.slice(offset, offset + pageSize);
  const hasMore = offset + pageSize < allResources.length;

  return {
    resources: page,
    nextCursor: hasMore ? encodeCursor(offset + pageSize) : undefined
  };
}

